import { FC, memo } from 'react';
import { choiceColorSet } from '../../modules/choiceColorSet';
import { panelCheck } from '../../modules/panelCheck';
import { ColorType, Panel } from '../../modules/types';

type Props = {
  colorSet: (num: number) => void;
};

export const ChoiceColor: FC<Props> = memo((props) => {
  return (
    <>
      <div>
        <div className="play">
          <RedButton colorSet={props.colorSet} />
          <GreenButton colorSet={props.colorSet} />
          <WhiteButton colorSet={props.colorSet} />
          <BlueButton colorSet={props.colorSet} />
        </div>
        <YellowButton colorSet={props.colorSet}></YellowButton>
        <p>更新で最初からに戻ります。</p>
      </div>
    </>
  );
});
